import re
from typing import Any

from app.core.config import settings
from app.core.logging import logger
from app.graph.state import EvaluationState


def calculate_mock_ai_probability(text: str) -> tuple[float, str]:
    """Analyze text for synthetic indicators and formulaic structural patterns."""
    text_lower = text.lower()

    # Synthetic marker markers frequently generated by common LLMs
    synthetic_markers = [
        r"\bin the contemporary era\b",
        r"\bit is crucial to remember that\b",
        r"\bin conclusion, it is vital\b",
        r"\bmoreover, another crucial aspect\b",
        r"\bdelving into\b",
        r"\btestament to\b",
        r"\bplays a pivotal role in the tapestry\b",
    ]

    matches = 0
    for marker in synthetic_markers:
        if re.search(marker, text_lower):
            matches += 1

    # Base score determined by synthetic phrasing
    if matches >= 2:
        probability = min(0.85 + (matches * 0.05), 0.98)
        rationale = (
            "El texto exhibe patrones léxicos altamente formulaicos y estructuras "
            "típicas de modelos generativos (transiciones rígidas y baja variabilidad de interlengua)."
        )
    elif matches == 1:
        probability = 0.72
        rationale = (
            "Se detectan conectores y construcciones oracionales con características "
            "de texto asistido por IA."
        )
    else:
        # Standard human student writing
        probability = 0.12
        rationale = (
            "La redacción muestra variabilidad natural en la longitud de oraciones, "
            "expresión idiosincrática y rasgos genuinos de redacción de estudiante."
        )

    return probability, rationale


async def ai_detector_node(state: EvaluationState) -> dict[str, Any]:
    """Evaluates probability of AI-generated content and flags potential alerts."""
    text = state.get("sanitized_text", state.get("student_text", ""))
    logger.info("Running ai_detector_node for text length %d", len(text))

    if settings.LLM_PROVIDER == "mock":
        prob, rationale = calculate_mock_ai_probability(text)
    else:
        prob, rationale = calculate_mock_ai_probability(text)

    threshold = settings.AI_DETECTION_THRESHOLD
    is_likely_ai = prob >= threshold
    confidence = "HIGH" if prob > 0.80 or prob < 0.30 else "MEDIUM"

    return {
        "ai_detection": {
            "probability": round(prob, 2),
            "is_likely_ai": is_likely_ai,
            "confidence": confidence,
            "rationale": rationale,
        }
    }
